+    public TickBarBuilder(final NumFactory numFactory, final int tickCount) {
+        this.numFactory = numFactory;
+        this.tickCount = tickCount;
+        reset();
+    }
+
+    @Override
+    public BarBuilder timePeriod(final Duration timePeriod) {
+        this.timePeriod = timePeriod;
